// ═══════════════════════════════════════════════════════════════
// Parse IoT Snapshot — build alerts + summary message
// ═══════════════════════════════════════════════════════════════
const body = $input.first().json.body;
const trigger   = body.trigger   || 'unknown';
const ts        = body.timestamp || '';
const weather   = body.weather_latest   || {};
const sensor    = body.sensor_latest    || {};
const relay     = body.relay_status     || {};
const alarm     = body.alarm            || {};
const ai        = body.ai_latest        || {};
const td        = body.trigger_data     || {};

const alerts = [];

// ── Critical: Alarm ────────────────────────────────────────────
if (alarm.active) {
  alerts.push({ level: 'CRITICAL', msg: `🚨 ALARM ACTIVATED\nReason: ${alarm.reason}` });
}

// ── Relay change ───────────────────────────────────────────────
if (trigger === 'relay') {
  const icon = td.new_state === 'ON' ? '🟢' : '🔴';
  const srcMap = { mqtt:'ESP32', ai_agent:'AI Agent', threshold:'Auto-Threshold', dashboard:'Dashboard' };
  alerts.push({ level: 'INFO', msg: `${icon} Relay ${td.relay_number}: ${td.old_state} → ${td.new_state}\nSource: ${srcMap[td.source]||td.source}\nReason: ${td.reason||'-'}` });
}

// ── Alarm event ─────────────────────────────────────────────────
if (trigger === 'alarm') {
  const icon = td.alarm_active ? '🚨' : '✅';
  alerts.push({ level: td.alarm_active ? 'CRITICAL' : 'INFO', msg: `${icon} Alarm ${td.alarm_state}\n${td.reason||''}` });
}

// ── AI decision ─────────────────────────────────────────────────
if (trigger === 'ai') {
  const icon = td.decision === 'on' ? '✅' : '🛑';
  alerts.push({ level: 'INFO', msg: `🤖 AI: Relay ${td.relay_number} → ${td.command} (${icon} ${td.decision?.toUpperCase()})\nConfidence: ${td.confidence_pct}%\n${td.reasoning_summary||''}` });
}

// ── Weather thresholds ──────────────────────────────────────────
if ((weather.rain_probability || 0) >= 70)
  alerts.push({ level: 'WARNING', msg: `🌧 Rain: ${weather.rain_probability}% — Consider closing the greenhouse` });
if ((weather.temperature || 0) >= 38)
  alerts.push({ level: 'WARNING', msg: `🌡 Outdoor Temp: ${weather.temperature}°C` });
if ((weather.aqi || 0) >= 4)
  alerts.push({ level: 'WARNING', msg: `🏭 AQI ${weather.aqi} (${weather.aqi_label}) — PM2.5: ${weather.pm2_5} μg/m³` });

// ── Sensor thresholds ───────────────────────────────────────────
if ((sensor.temperature || 0) >= 35)
  alerts.push({ level: 'WARNING', msg: `🌡 Indoor Temp: ${sensor.temperature}°C` });
if ((sensor.humidity || 0) >= 90)
  alerts.push({ level: 'WARNING', msg: `💧 Humidity: ${sensor.humidity}%` });

// ── Full summary message ─────────────────────────────────────────
const summaryLines = [
  `📡 IoT Snapshot [${trigger.toUpperCase()}] — ${ts}`,
  '',
];

if (weather.city_name) {
  summaryLines.push(
    `🌤 Weather: ${weather.weather_desc} | ${weather.temperature}°C (feels ${weather.feels_like}°C)`,
    `   Hum: ${weather.humidity}% | Wind: ${weather.wind_speed}m/s | Rain: ${weather.rain_probability}%`,
    `   AQI: ${weather.aqi} (${weather.aqi_label}) | PM2.5: ${weather.pm2_5} μg/m³`,
  );
}

if (sensor.device_name) {
  summaryLines.push(
    ``,
    `🌡 Sensor (${sensor.device_name})`,
    `   Temp: ${sensor.temperature}°C | Hum: ${sensor.humidity}% | DS18B20: ${sensor.ds18b20}°C`,
  );
}

summaryLines.push(
  ``,
  `🔌 Relay: R1=${relay.relay1?'ON':'OFF'} R2=${relay.relay2?'ON':'OFF'} R3=${relay.relay3?'ON':'OFF'}`,
  `🤖 AI: ${ai.decision?.toUpperCase()||'N/A'} (${ai.confidence_pct||0}%)`,
  `🚨 Alarm: ${alarm.active ? 'ACTIVE — '+alarm.reason : 'Normal'}`,
);

if (alerts.length) {
  summaryLines.push('', '⚠️ Alerts:', ...alerts.map(a => `  [${a.level}] ${a.msg}`));
}

return [{
  json: {
    trigger,
    has_alerts:      alerts.length > 0,
    highest_level:   alerts.some(a=>a.level==='CRITICAL') ? 'CRITICAL'
                   : alerts.some(a=>a.level==='WARNING')  ? 'WARNING' : 'INFO',
    alerts,
    summary_message: summaryLines.join('\n'),
    // pass raw sections downstream
    weather, sensor, relay, alarm, ai, trigger_data: td, timestamp: ts,
  }
}];
